// Package snapshot saves the store to a JSON file and loads it back, so the server keeps its data across restarts. The
// file carries a version; files written by older versions of Tally are migrated when they are loaded, and Upgrade
// rewrites them in place.
package snapshot

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"time"

	"example.com/tally/internal/money"
	"example.com/tally/internal/store"
)

// Version is the version Save writes.
const Version = 3

// ErrUnsupportedVersion is returned for a file of a version Load cannot read.
var ErrUnsupportedVersion = errors.New("unsupported snapshot version")

type fileV2 struct {
	Version int         `json:"version"`
	SavedAt time.Time   `json:"saved_at"`
	State   store.State `json:"state"`
}

type fileV3 struct {
	Version int         `json:"version"`
	SavedAt time.Time   `json:"saved_at"`
	State   store.State `json:"state"`
}

// Save writes everything in st to path. The file is replaced atomically: a crash leaves either the previous snapshot or
// the whole new one.
func Save(st *store.Store, path string, now time.Time) error {
	b, err := json.MarshalIndent(fileV3{Version: Version, SavedAt: now.UTC(), State: st.Export()}, "", "  ")
	if err != nil {
		return err
	}
	return writeFileAtomic(path, append(b, '\n'))
}

// Load reads a snapshot written by Save, or by an older version of Tally, and returns a store holding it.
func Load(path string) (*store.Store, error) {
	b, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	st, _, err := decode(path, b)
	return st, err
}

// Upgrade rewrites the snapshot at path as the current version. The original bytes are first copied to
// "<path>.v<old version>.bak". A file that is already current is left alone, without a backup; a file of a version
// Load cannot read is refused and left untouched.
func Upgrade(path string) error {
	b, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	st, version, err := decode(path, b)
	if err != nil {
		return err
	}
	if version == Version {
		return nil
	}
	if err := writeBackup(fmt.Sprintf("%s.v%d.bak", path, version), b); err != nil {
		return err
	}
	return Save(st, path, time.Now())
}

// decode reads the snapshot in b, which was read from path, and returns the store it holds and its version.
func decode(path string, b []byte) (*store.Store, int, error) {
	var head struct {
		Version int `json:"version"`
	}
	if err := json.Unmarshal(b, &head); err != nil {
		return nil, 0, fmt.Errorf("snapshot %s: %w", path, err)
	}
	var st store.State
	switch head.Version {
	case 1:
		var err error
		if st, err = migrateV1(b); err != nil {
			return nil, 0, fmt.Errorf("snapshot %s: version 1: %w", path, err)
		}
	case 2:
		var f fileV2
		if err := json.Unmarshal(b, &f); err != nil {
			return nil, 0, fmt.Errorf("snapshot %s: %w", path, err)
		}
		st = f.State
	case 3:
		var f fileV3
		if err := json.Unmarshal(b, &f); err != nil {
			return nil, 0, fmt.Errorf("snapshot %s: %w", path, err)
		}
		st = f.State
	default:
		return nil, 0, fmt.Errorf("snapshot %s: %w %d", path, ErrUnsupportedVersion, head.Version)
	}
	s, err := store.FromState(st)
	return s, head.Version, err
}

// writeBackup copies b to path, unless path already holds the same bytes. An existing backup with other contents is
// never overwritten.
func writeBackup(path string, b []byte) error {
	old, err := os.ReadFile(path)
	switch {
	case err == nil:
		if bytes.Equal(old, b) {
			return nil
		}
		return fmt.Errorf("backup %s already exists with different contents", path)
	case !errors.Is(err, os.ErrNotExist):
		return err
	}
	return writeFileAtomic(path, b)
}

// writeFileAtomic replaces the file at path with data. The data goes to a temporary file in the same folder, which is
// synced and renamed over path. The temporary file is removed when anything fails.
func writeFileAtomic(path string, data []byte) (err error) {
	dir := filepath.Dir(path)
	f, err := os.CreateTemp(dir, filepath.Base(path)+".tmp-*")
	if err != nil {
		return err
	}
	defer func() {
		if err != nil {
			_ = f.Close()
			_ = os.Remove(f.Name())
		}
	}()
	if _, err = f.Write(data); err != nil {
		return err
	}
	if err = f.Sync(); err != nil {
		return err
	}
	if err = f.Close(); err != nil {
		return err
	}
	if err = os.Rename(f.Name(), path); err != nil {
		return err
	}
	syncDir(dir)
	return nil
}

// syncDir makes the rename durable. It is best effort: some platforms cannot sync a folder.
func syncDir(dir string) {
	d, err := os.Open(dir)
	if err != nil {
		return
	}
	_ = d.Sync()
	_ = d.Close()
}

