func TestSaveWritesVersion3WithNumbers(t *testing.T) {
	now := time.Date(2026, 2, 1, 12, 0, 0, 0, time.UTC)
	st := store.New()
	o, _ := st.CreateOrg("A", store.OrgTeam, "UTC", 0, now)
	c, _ := st.CreateCustomer(o.ID, "Jane", "jane@example.com", now)
	inv, _ := st.CreateInvoice(store.Invoice{OrgID: o.ID, CustomerID: c.ID, Currency: money.USD, Lines: []store.Line{{Description: "x", Quantity: 1, UnitAmount: 100}}}, now)

	dir := t.TempDir()
	path := filepath.Join(dir, "tally.json")
	if err := Save(st, path, now); err != nil {
		t.Fatal(err)
	}
	b, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	var f struct {
		Version int `json:"version"`
		State   struct {
			NextInvoiceNos map[string]int `json:"next_invoice_numbers"`
			Invoices       []struct {
				Number string `json:"number"`
			} `json:"invoices"`
		} `json:"state"`
	}
	if err := json.Unmarshal(b, &f); err != nil {
		t.Fatal(err)
	}
	if f.Version != 3 || len(f.State.Invoices) != 1 || f.State.Invoices[0].Number != inv.Number || f.State.NextInvoiceNos[o.ID] != 2 {
		t.Fatalf("file = %s", b)
	}
	if inv.Number != "INV-000001" {
		t.Fatalf("number = %q", inv.Number)
	}
	entries, _ := os.ReadDir(dir)
	if len(entries) != 1 || entries[0].Name() != "tally.json" {
		t.Fatalf("the folder holds %v after Save", entries)
	}
}

func TestSaveReplacesTheWholeFile(t *testing.T) {
	now := time.Date(2026, 2, 1, 12, 0, 0, 0, time.UTC)
	dir := t.TempDir()
	path := filepath.Join(dir, "tally.json")
	if err := os.WriteFile(path, []byte(strings.Repeat("old garbage ", 5000)), 0o600); err != nil {
		t.Fatal(err)
	}
	st := store.New()
	if _, err := st.CreateOrg("A", store.OrgTeam, "UTC", 0, now); err != nil {
		t.Fatal(err)
	}
	if err := Save(st, path, now); err != nil {
		t.Fatal(err)
	}
	got, err := Load(path)
	if err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(got.Export(), st.Export()) {
		t.Fatal("the file does not hold the whole new snapshot")
	}
	if entries, _ := os.ReadDir(dir); len(entries) != 1 {
		t.Fatalf("the folder holds %d files after Save", len(entries))
	}
}

func TestSaveFailureKeepsTheOldFile(t *testing.T) {
	now := time.Date(2026, 2, 1, 12, 0, 0, 0, time.UTC)
	st := store.New()
