		t.Fatalf("next numbers = %v", got)
	}
}

func TestFromStateNumbersInvoices(t *testing.T) {
	s := New()
	a := newOrg(t, s, "A")
	c, _ := s.CreateCustomer(a.ID, "Jane", "jane@example.com", t0)
	line := []Line{{Description: "x", Quantity: 1, UnitAmount: 100}}
	inv, _ := s.CreateInvoice(Invoice{OrgID: a.ID, CustomerID: c.ID, Currency: money.USD, Lines: line}, t0)
	st := s.Export()

	// Without numbers, invoices are numbered from 1 in creation order, and the next number follows them.
	st.Invoices[0].Number = ""
	st.NextInvoiceNos = nil
	st.Invoices = append(st.Invoices, Invoice{ID: "in_999999", OrgID: a.ID, CustomerID: c.ID, Currency: money.USD, Lines: line, CreatedAt: t0.Add(time.Hour)})
	s2, err := FromState(st)
	if err != nil {
		t.Fatal(err)
	}
	if got, _ := s2.InvoiceByID(inv.ID); got.Number != "INV-000001" {
		t.Fatalf("first invoice = %q", got.Number)
	}
	if got, _ := s2.InvoiceByID("in_999999"); got.Number != "INV-000002" {
		t.Fatalf("second invoice = %q", got.Number)
	}
	next, _ := s2.CreateInvoice(Invoice{OrgID: a.ID, CustomerID: c.ID, Currency: money.USD, Lines: line}, t0)
	if next.Number != "INV-000003" {
		t.Fatalf("next invoice = %q", next.Number)
	}

	// A recorded next number is kept when it is higher than the numbers in use.
	st = s.Export()
	st.NextInvoiceNos = map[string]int{a.ID: 10}
	s3, err := FromState(st)
	if err != nil {
		t.Fatal(err)
	}
	if next, _ := s3.CreateInvoice(Invoice{OrgID: a.ID, CustomerID: c.ID, Currency: money.USD, Lines: line}, t0); next.Number != "INV-000010" {
		t.Fatalf("next invoice = %q", next.Number)
	}

	for _, bad := range []string{"INV-000000", "INV-1", "inv-000001", "INV-000001x", "INV-00000a"} {
		st = s.Export()
		st.Invoices[0].Number = bad
		if _, err := FromState(st); !errors.Is(err, ErrInvalid) {
			t.Errorf("number %q accepted: %v", bad, err)
		}
	}
	st = s.Export()
	dup := st.Invoices[0]
	dup.ID = "in_999998"
	st.Invoices = append(st.Invoices, dup)
	if _, err := FromState(st); !errors.Is(err, ErrInvalid) {
		t.Fatalf("a repeated number was accepted: %v", err)
	}
}
